import urllib.request, ssl, xml.etree.ElementTree as ET, re
from email.utils import parsedate_to_datetime
from datetime import datetime, timezone, timedelta
UA='Mozilla/5.0 (compatible; OpenClawScout/1.0)'
feeds={
'CoinDesk':'https://www.coindesk.com/arc/outboundfeeds/rss/',
'CoinTelegraph':'https://cointelegraph.com/rss',
'Decrypt':'https://decrypt.co/feed',
'GoogleNews':'https://news.google.com/rss/search?q=cryptocurrency+OR+blockchain+OR+ethereum+OR+solana+OR+altcoin+OR+%22digital+assets%22+OR+XRP+OR+cardano+-dogecoin+-shiba+-pepe+-floki+-bonk+-wif+-memecoin+-%22meme+coin%22&hl=en-US&gl=US&ceid=US:en',
'BeInCrypto':'https://beincrypto.com/feed/',
'TheBlock':'https://www.theblock.co/rss.xml',
'CryptoSlate':'https://cryptoslate.com/feed/',
'CryptoFoxMarkets':'https://cryptofox.news/rss/markets/',
'CryptoFoxRegulation':'https://cryptofox.news/rss/regulation/',
}
ctx=ssl.create_default_context(); ctx.check_hostname=False; ctx.verify_mode=ssl.CERT_NONE
cutoff=datetime(2026,5,20,11,10,tzinfo=timezone.utc)
for name,url in feeds.items():
    print(f'### {name}')
    try:
        data=urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent':UA}), context=ctx, timeout=20).read()
        root=ET.fromstring(data)
        items=root.findall('.//item') or root.findall('.//{http://www.w3.org/2005/Atom}entry')
        count=0
        for it in items:
            title=it.findtext('title') or it.findtext('{http://www.w3.org/2005/Atom}title') or ''
            link=it.findtext('link') or ''
            if not link:
                l=it.find('{http://www.w3.org/2005/Atom}link')
                if l is not None:
                    link=l.attrib.get('href','')
            pub=it.findtext('pubDate') or it.findtext('{http://www.w3.org/2005/Atom}published') or it.findtext('{http://www.w3.org/2005/Atom}updated') or ''
            dt=None
            if pub:
                try:
                    dt=parsedate_to_datetime(pub)
                except Exception:
                    try:
                        dt=datetime.fromisoformat(pub.replace('Z','+00:00'))
                    except Exception:
                        pass
            if dt and dt.tzinfo is None:
                dt=dt.replace(tzinfo=timezone.utc)
            if dt and dt >= cutoff:
                desc=it.findtext('description') or it.findtext('{http://www.w3.org/2005/Atom}summary') or ''
                desc=re.sub(r'\s+',' ',re.sub('<[^>]+>',' ',desc)).strip()
                print(f'- {dt.isoformat()} | {title[:120]}')
                if link: print(f'  {link}')
                if desc: print(f'  {desc[:180]}')
                count+=1
                if count>=8: break
        if count==0:
            print('  (no items in last 24h found in first batch or parse issue)')
    except Exception as e:
        print('ERROR',type(e).__name__,e)
    print()
PY
